import 'package:flutter/widgets.dart';

/// Localizes application-owned authentication and settings copy only.
/// Values supplied through placeholders are never looked up or translated.
String authSettingsText(BuildContext context, String key, [Map<String, Object?> values = const {}]) =>
    authSettingsTextForLocale(Localizations.localeOf(context).languageCode, key, values);

String authSettingsTextForLocale(String language, String key, [Map<String, Object?> values = const {}]) {
  final entry = authSettingsCatalog[key];
  final template = entry == null ? key : entry[language == 'fr' ? 1 : 0];
  final localized = language == 'ar' ? key : template;
  return localized.replaceAllMapped(RegExp(r'\{([a-zA-Z]+)\}'), (match) => values.containsKey(match[1]) ? values[match[1]].toString() : match[0]!);
}

